"""Original query texts, frozen as first written (default graph, no views, label-anchored). Compared in query_bench.py."""

Q = {'Q1': 'PREFIX ex: <urn:repronim:abide:>\nPREFIX prov: <http://www.w3.org/ns/prov#>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX dct: <http://purl.org/dc/terms/>\nPREFIX nidm: <http://purl.org/nidash/nidm#>\nSELECT ?cohort ?dx (COUNT(DISTINCT ?p) AS ?n) WHERE {\n  VALUES ?cohort { <urn:repronim:abide:cohort/B_v1> <urn:repronim:abide:cohort/B_v2> <urn:repronim:abide:cohort/abraham2017_reconstructed> }\n  ?cohort prov:hadMember ?p . ?rec ex:participant ?p ; <urn:repronim:abide:variable/DX_GROUP> ?dx .\n} GROUP BY ?cohort ?dx ORDER BY ?cohort ?dx', 'Q2': 'PREFIX ex: <urn:repronim:abide:>\nPREFIX prov: <http://www.w3.org/ns/prov#>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX dct: <http://purl.org/dc/terms/>\nPREFIX nidm: <http://purl.org/nidash/nidm#>\nSELECT\n  (COUNT(DISTINCT ?both) AS ?overlap)\n  (COUNT(DISTINCT ?dropped) AS ?bTestExcludedByV2)\nWHERE {\n  { <urn:repronim:abide:cohort/A_v1> prov:hadMember ?both . <urn:repronim:abide:cohort/B_v1> prov:hadMember ?both . }\n  UNION\n  { ?fold dct:isPartOf <urn:repronim:abide:analysis/B_v1> ; ex:testedOn ?c . ?c ex:participant ?dropped .\n    FILTER NOT EXISTS { <urn:repronim:abide:cohort/B_v2> prov:hadMember ?dropped } }\n}', 'Q3': 'PREFIX ex: <urn:repronim:abide:>\nPREFIX prov: <http://www.w3.org/ns/prov#>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX dct: <http://purl.org/dc/terms/>\nPREFIX nidm: <http://purl.org/nidash/nidm#>\nSELECT ?conn ?method ?ts ?tsUrl ?tsSha ?pre ?software ?raw ?rawUrl ?cfg ?strategy ?nuisance ?gsr ?bandpass WHERE {\n  ?p rdfs:label "%s" .\n  ?conn a nidm:DerivativeObject ; ex:participant ?p ; prov:wasDerivedFrom ?ts ; prov:wasGeneratedBy ?ca .\n  ?ca ex:method ?method .\n  ?ts prov:atLocation ?tsUrl ; <http://id.loc.gov/vocabulary/preservation/cryptographicHashFunctions#sha256> ?tsSha ; prov:wasGeneratedBy ?pre .\n  ?pre prov:wasAssociatedWith ?swa ; prov:used ?raw , ?cfg . ?swa rdfs:label ?software .\n  ?raw a nidm:AcquisitionObject ; prov:atLocation ?rawUrl .\n  ?cfg ex:strategy ?strategy ; ex:nuisance ?nuisance ; ex:globalSignalRegression ?gsr ; ex:bandpassHz ?bandpass .\n}', 'Q4': 'PREFIX ex: <urn:repronim:abide:>\nPREFIX prov: <http://www.w3.org/ns/prov#>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX dct: <http://purl.org/dc/terms/>\nPREFIX nidm: <http://purl.org/nidash/nidm#>\nSELECT ?paper ?question ?claim ?claimType ?scope ?quote ?locator ?cohortQuote WHERE {\n  ?claim a ex:Claim ; ex:statedIn ?paper ; ex:claimType ?claimType ; ex:scope ?scope ; ex:addresses ?q ; ex:hasEvidence ?ev .\n  ?ev ex:quote ?quote ; ex:locator ?locator .\n  ?q ex:hasEvidence ?qe . ?qe ex:quote ?question .\n  OPTIONAL { ?claim ex:dependsOn ?coh . ?coh a ex:ReportedCohort ; ex:hasEvidence ?ce . ?ce ex:quote ?cohortQuote . }\n} ORDER BY ?paper ?claim', 'Q5': 'PREFIX ex: <urn:repronim:abide:>\nPREFIX prov: <http://www.w3.org/ns/prov#>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX dct: <http://purl.org/dc/terms/>\nPREFIX nidm: <http://purl.org/nidash/nidm#>\nSELECT ?kind (COUNT(DISTINCT ?e) AS ?nFlagged) WHERE {\n  ?e ex:flaggedForReassessmentBy ?act . ?e a ?kind .\n  FILTER (?kind IN (ex:Result, ex:Claim, ex:EvidenceAssessment))\n} GROUP BY ?kind', 'Q5b': 'PREFIX ex: <urn:repronim:abide:>\nPREFIX prov: <http://www.w3.org/ns/prov#>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX dct: <http://purl.org/dc/terms/>\nPREFIX nidm: <http://purl.org/nidash/nidm#>\nSELECT ?change ?summary ?material WHERE {\n  ?change a ex:MeasuredChange ; ex:summary ?summary ; ex:materialChange ?material .\n} ORDER BY ?change', 'Q6': 'PREFIX ex: <urn:repronim:abide:>\nPREFIX prov: <http://www.w3.org/ns/prov#>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX dct: <http://purl.org/dc/terms/>\nPREFIX nidm: <http://purl.org/nidash/nidm#>\nSELECT ?review ?verdict ?d ?nInd ?nSites ?nConsistent ?caveat WHERE {\n  VALUES ?review { <urn:repronim:abide:review/B_reviews_A_v1> <urn:repronim:abide:review/B_reviews_A_v2> }\n  ?review ex:verdict ?verdict ; ex:pooled_d_fixed_effect ?d ; ex:n_independent_participants ?nInd ;\n          ex:n_sites_usable ?nSites ; ex:n_sites_direction_consistent ?nConsistent ; ex:caveat ?caveat .\n}', 'Q7': 'PREFIX ex: <urn:repronim:abide:>\nPREFIX prov: <http://www.w3.org/ns/prov#>\nPREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX dct: <http://purl.org/dc/terms/>\nPREFIX nidm: <http://purl.org/nidash/nidm#>\nSELECT ?review ?reviewer ?role ?target ?evidence ?verdict WHERE {\n  ?review a ex:EvidenceAssessment ; prov:wasAttributedTo ?r ; ex:target ?target ; ex:verdict ?verdict ;\n          prov:wasDerivedFrom ?evidence ; prov:wasGeneratedBy ?act .\n  ?r rdfs:label ?reviewer .\n  ?act prov:qualifiedAssociation ?as . ?as prov:agent ?r ; prov:hadRole ?role .\n} ORDER BY ?review ?evidence'}
Q_PARTICIPANTS = 'PREFIX ex: <urn:repronim:abide:>\nPREFIX prov: <http://www.w3.org/ns/prov#>\nPREFIX dct: <http://purl.org/dc/terms/>\n\nSELECT ?cohort ?participant ?fd WHERE {\n  ?new prov:wasRevisionOf ?old ; ex:threshold ?thr ; ex:variable ?var .\n  ?sel prov:used ?old .\n  ?cohort prov:wasGeneratedBy ?sel ; prov:hadMember ?participant .\n  ?rec ex:participant ?participant ; ?var ?fd .\n  FILTER (?fd >= ?thr)\n}'
Q_FOLDS = 'PREFIX ex: <urn:repronim:abide:>\nPREFIX prov: <http://www.w3.org/ns/prov#>\nPREFIX dct: <http://purl.org/dc/terms/>\n\nSELECT ?fold ?site (SUM(?isTest) AS ?nTest) (SUM(?isTrain) AS ?nTrain) WHERE {\n  ?new prov:wasRevisionOf ?old ; ex:threshold ?thr ; ex:variable ?var .\n  ?sel prov:used ?old . ?cohort prov:wasGeneratedBy ?sel ; prov:hadMember ?p .\n  ?rec ex:participant ?p ; ?var ?fd . FILTER (?fd >= ?thr)\n  ?conn ex:participant ?p .\n  ?fold ex:heldOutSite ?site .\n  { ?fold ex:testedOn ?conn . BIND(1 AS ?isTest) BIND(0 AS ?isTrain) }\n  UNION\n  { ?fold ex:trainedOn ?conn . BIND(0 AS ?isTest) BIND(1 AS ?isTrain) }\n} GROUP BY ?fold ?site ORDER BY ?site'
Q_DOWNSTREAM = 'PREFIX ex: <urn:repronim:abide:>\nPREFIX prov: <http://www.w3.org/ns/prov#>\nPREFIX dct: <http://purl.org/dc/terms/>\n\nSELECT DISTINCT ?entity ?kind WHERE {\n  ?new prov:wasRevisionOf ?old .\n  ?sel prov:used ?old . ?cohort prov:wasGeneratedBy ?sel .\n  {\n    ?analysis prov:used ?cohort .\n    { ?entity prov:wasGeneratedBy ?analysis . BIND("result" AS ?kind) }\n    UNION { ?fold dct:isPartOf ?analysis . ?entity prov:wasGeneratedBy ?fold . BIND("fold_result" AS ?kind) }\n    UNION { ?fold dct:isPartOf ?analysis . ?r prov:wasGeneratedBy ?fold . ?entity prov:wasDerivedFrom ?r . BIND("pooled_result" AS ?kind) }\n  }\n  UNION\n  {\n    ?analysis prov:used ?cohort .\n    { ?r prov:wasGeneratedBy ?analysis } UNION { ?fold dct:isPartOf ?analysis . ?fr prov:wasGeneratedBy ?fold . ?r prov:wasDerivedFrom ?fr }\n    ?entity prov:wasDerivedFrom+ ?r .\n    ?entity a ?t . FILTER (?t IN (ex:Claim, ex:EvidenceAssessment))\n    BIND("claim_or_review" AS ?kind)\n  }\n  UNION\n  { ?entity prov:wasDerivedFrom ?cohort . BIND("result" AS ?kind) }\n}'
Q_SITE_ELIGIBILITY = 'PREFIX ex: <urn:repronim:abide:>\nPREFIX prov: <http://www.w3.org/ns/prov#>\nPREFIX dct: <http://purl.org/dc/terms/>\n\nSELECT ?site ?dx (COUNT(DISTINCT ?p) AS ?remaining) WHERE {\n  ?new prov:wasRevisionOf ?old ; ex:threshold ?thr ; ex:variable ?var .\n  ?sel prov:used ?old , <urn:repronim:abide:rule/site_min> .\n  ?cohort prov:wasGeneratedBy ?sel ; prov:hadMember ?p .\n  ?p ex:site ?site .\n  ?rec ex:participant ?p ; ?var ?fd ; <urn:repronim:abide:variable/DX_GROUP> ?dx .\n  FILTER (?fd < ?thr)\n} GROUP BY ?site ?dx ORDER BY ?site ?dx'
PHENOTYPE_MATRIX = 'PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\nPREFIX ex: <urn:repronim:abide:>\nPREFIX prov: <http://www.w3.org/ns/prov#>\nSELECT ?fid ?site ?dx ?sex ?var ?value ?thick ?conn WHERE {\n  <urn:repronim:abide:cohort/B_v1> prov:hadMember ?p .\n  ?p rdfs:label ?fid ; ex:site ?site .\n  ?rec ex:participant ?p ; a <http://purl.org/nidash/nidm#AcquisitionObject> ;\n       <urn:repronim:abide:variable/DX_GROUP> ?dx ; <urn:repronim:abide:variable/SEX> ?sex .\n  OPTIONAL { ?rec ?var ?value . VALUES ?var { <urn:repronim:abide:variable/AGE_AT_SCAN> <urn:repronim:abide:variable/FIQ> <urn:repronim:abide:variable/VIQ> <urn:repronim:abide:variable/PIQ> <urn:repronim:abide:variable/SRS_RAW_TOTAL> } }\n  OPTIONAL { ?idp ex:participant ?p ; ex:meanCorticalThickness ?thick . }\n  OPTIONAL { ?c ex:participant ?p ; ex:meanFisherZ ?conn . }\n}'
